    AND (document ? 'smoothing_latitude_degrees' AND COALESCE(jsonb_typeof((document -> 'smoothing_latitude_degrees')) = 'number', FALSE))
    AND (NOT document ? 'source_location' OR COALESCE((CASE WHEN jsonb_typeof((document -> 'source_location')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'source_location')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END OR jsonb_typeof((document -> 'source_location')) = 'string' OR jsonb_typeof((document -> 'source_location')) = 'null'), FALSE))) ELSE FALSE END
WHEN 'watershed_boundary' THEN CASE WHEN jsonb_typeof(document) = 'object' THEN (
    document - ARRAY['method', 'boundary_id', 'basis', 'sources', 'lines', 'sections', 'joins', 'start', 'end', 'terrains', 'evidence_sources', 'geographic_choices']::text[] = '{}'::jsonb
    AND (document ? 'method' AND COALESCE(((document -> 'method') = '"watershed_boundary"'::jsonb), FALSE))
    AND (document ? 'boundary_id' AND COALESCE((jsonb_typeof((document -> 'boundary_id')) = 'string' AND ((document -> 'boundary_id') #>> '{}') COLLATE "C" ~ '[^[:space:]]'), FALSE))
    AND (document ? 'basis' AND COALESCE((jsonb_typeof((document -> 'basis')) = 'string' AND ((document -> 'basis') #>> '{}') COLLATE "C" ~ '[^[:space:]]'), FALSE))
    AND (document ? 'sources' AND COALESCE(CASE WHEN jsonb_typeof((document -> 'sources')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'sources')) AS item0 WHERE NOT COALESCE(((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND (to_jsonb(item0.key) #>> '{}') COLLATE "C" ~ '[^[:space:]]') AND CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END), FALSE)) ELSE FALSE END, FALSE))
    AND (document ? 'lines' AND COALESCE(CASE WHEN jsonb_typeof((document -> 'lines')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'lines')) AS item0 WHERE NOT COALESCE(((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND (to_jsonb(item0.key) #>> '{}') COLLATE "C" ~ '[^[:space:]]') AND CASE WHEN jsonb_typeof(item0.value) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements(item0.value) AS item1(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item1.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item1.value) AS item2 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item2.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END), FALSE)) ELSE FALSE END, FALSE))
    AND (document ? 'sections' AND COALESCE(CASE WHEN jsonb_typeof((document -> 'sections')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((document -> 'sections')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (document ? 'joins' AND COALESCE(CASE WHEN jsonb_typeof((document -> 'joins')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((document -> 'joins')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (document ? 'start' AND COALESCE(CASE WHEN jsonb_typeof((document -> 'start')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'start')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))
    AND (document ? 'end' AND COALESCE(CASE WHEN jsonb_typeof((document -> 'end')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'end')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))
    AND (NOT document ? 'terrains' OR COALESCE((CASE WHEN jsonb_typeof((document -> 'terrains')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'terrains')) AS item0 WHERE NOT COALESCE(((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND (to_jsonb(item0.key) #>> '{}') COLLATE "C" ~ '[^[:space:]]') AND CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END), FALSE)) ELSE FALSE END OR jsonb_typeof((document -> 'terrains')) = 'null'), FALSE))
    AND (NOT document ? 'evidence_sources' OR COALESCE((CASE WHEN jsonb_typeof((document -> 'evidence_sources')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((document -> 'evidence_sources')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND (jsonb_typeof(item1.value) = 'string' AND (item1.value #>> '{}') COLLATE "C" ~ '[^[:space:]]')), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END OR jsonb_typeof((document -> 'evidence_sources')) = 'null'), FALSE))
    AND (NOT document ? 'geographic_choices' OR COALESCE((CASE WHEN jsonb_typeof((document -> 'geographic_choices')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((document -> 'geographic_choices')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END OR jsonb_typeof((document -> 'geographic_choices')) = 'null'), FALSE))) ELSE FALSE END
ELSE FALSE END;
$contract$;
ALTER TABLE atlas.construction_records ADD CONSTRAINT construction_document_valid
CHECK (atlas.valid_construction_record(document));
